<include file="Public:header"/><style type="text/css">    .table-list th{        width: 8%;    }</style><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Qiye/settlement')}" class="on">结算审核</a>|				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td style="width:60%;">						<form action="{pigcms{:U('Qiye/settlement')}" method="get">                            <input type="hidden" name="c" value="Qiye"/>                            <input type="hidden" name="a" value="settlement"/>							<input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>							<select name="searchtype">                                <option value="all" <if condition="$_GET['searchtype'] eq 'all'">selected="selected"</if>>请选择</option>								<option value="qiye_name" <if condition="$_GET['searchtype'] eq 'qiye_name'">selected="selected"</if>>企业名称</option>							</select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;							状态: <select name="searchstatus">                                <option value="-1" <if condition="$_GET['searchstatus'] eq -1">selected="selected"</if>>全部</option>                                <option value="0" <if condition="$_GET['searchstatus'] eq 0">selected="selected"</if>>待审核</option>								<option value="1" <if condition="$_GET['searchstatus'] eq 1">selected="selected"</if>>通过</option>								<option value="2" <if condition="$_GET['searchstatus'] eq 2">selected="selected"</if>>驳回</option>							</select>							<input type="submit" value="查询" class="button"/>						</form>					</td>					<notempty name="export">					<td>						<a  href="javascript:void(0)" onclick="exports()" class="button" style="float:right;margin-right: 10px;">导出列表</a>					</td>					</notempty>				</tr>			</table>				<div class="table-list">					<table width="100%" cellspacing="0">						<thead>							<tr>                                <th>序号</th>								<th>企业ID</th>                                <th>企业名称</th>                                <th>区域</th>                                <th>结算方式</th>                                <th>结算金额</th>                                <th>提交时间</th>                                <th>付款时间</th>                                <th>审核状态</th>                                <th>审核人</th>                                <th>审核备注</th>                                <th>操作</th>						</thead>						<tbody>                        <notempty name="list">                            <volist name="list" id="l">                                <tr>                                    <td>{pigcms{$l.id}</td>                                    <td>{pigcms{$l.account}</td>                                    <td>{pigcms{$l.qiye_name}</td>                                    <td>{pigcms{$l.address}</td>                                    <td><if condition="$l['settlement_type'] eq 1"><font color="green">先消费后结算</font><else/><font color="red">先结算后消费</font></if></td>                                    <td>{pigcms{$l.money}</td>                                    <td>{pigcms{$l.apply_time|date='Y-m-d H:i:s',###}</td>                                    <td>{pigcms{$l.pay_date}</td>                                    <td>                                        <if condition="$l['status'] eq 0">                                            待审核                                            <elseif condition="$l['status'] EQ 1"/>                                            通过                                            <else/>                                            驳回                                        </if>                                    </td>                                    <td>{pigcms{$l.admin_account}</td>                                    <td>{pigcms{$l.handle_remark}</td>                                    <td>                                        <if condition="$l['status'] EQ 0">                                            <a href="javascript:vod(0)" onclick="handle('{pigcms{$l.id}')">审核</a>    |                                        </if>                                            <a href="javascript:vod(0)" onclick="detail('{pigcms{$l.id}')">查看</>                                    </td>                                </tr>                            </volist>                            <tr><td class="textcenter pagebar" colspan="13">{pigcms{$pagebar}</td></tr>                        <else/>                            <tr><td class="textcenter red" colspan="13">列表为空！</td></tr>                        </notempty>						</tbody>					</table>				</div>		</div><script>  function handle(id){      window.top.artiframe('{pigcms{:U('Qiye/handleSettlement')}'+'&id='+id,'审核',800,500,true,false,false,addbtn,'add',true);  }  function detail(id){      window.top.artiframe('{pigcms{:U('Qiye/settlementDetail')}'+'&id='+id,'查看',800,500,true,false,false,false,'add',true);  }</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>